# Generated by release/homebrew/formula.sh of the wolfpack repository for each release.
class Wolfpack < Formula
  desc "Statically typed language that compiles to readable TypeScript, Go and Rust"
  homepage "https://github.com/realfamousbae/wolfpack"
  license any_of: ["MIT", "Apache-2.0"]

  # The macOS archive is universal: the same file for both processors.
  on_macos do
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.0/wolfpack-macos-universal.tar.gz"
      sha256 "422cd02779a40e38004f555c5d51afdfbc724456aa94661df6018a8bcc4482aa"
    end
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.0/wolfpack-macos-universal.tar.gz"
      sha256 "422cd02779a40e38004f555c5d51afdfbc724456aa94661df6018a8bcc4482aa"
    end
  end

  on_linux do
    on_intel do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.0/wolfpack-linux-x64.tar.gz"
      sha256 "00e0380bc4ecd127cac504aeeae6637b08413c14093c4ea3afe733a409323f94"
    end
    on_arm do
      url "https://github.com/realfamousbae/wolfpack/releases/download/v0.5.0/wolfpack-linux-arm64.tar.gz"
      sha256 "cb57a1e43f8a6e51da33614b650292a170a8a85170e6e159ccd53d30994a634b"
    end
  end

  def install
    bin.install "wolf"
  end

  def caveats
    <<~EOS
      wolf runs programs in its own VM without other tools (wolf run --vm).
      To build and run them as TypeScript, Go or Rust, install those tools with:
        wolf setup
    EOS
  end

  test do
    assert_match version.to_s, shell_output("#{bin}/wolf --version")
    system bin/"wolf", "new", "hello"
    assert_equal "Hello, wolfpack!\n", shell_output("cd hello && #{bin}/wolf run --vm")
  end
end
